        .reverse()[0]
    },
    message() {
      return { doc_id: this.file.chat?.id }
    },
    chatProject() {
      return this.$storex.projects.allProjectsById[this.prChat?.project_id]
        || this.$projects.allProjectsById[this.prChat?.owner_project_id]
        || this.$project
    }
